def hillis_steele(xs):
    """Inclusive scan by Hillis-Steele: at stride s = 1, 2, 4, ..., every element t >= s adds the element s places
    back, all elements of one step at once (as the threads of hillisSteele do). Returns a new list."""
    a = list(xs)
    s = 1
    while s < len(a):
        for t in range(len(a)):
